using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.Data;
using System.Text;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Forms;
using DevExpress.XtraEditors;
using DevExpress.DataAccess.Sql;
namespace Jamera.Employees
{
    public partial class Employees : DevExpress.XtraEditors.XtraUserControl
    {
        public Employees()
        {
            InitializeComponent();

            // This line of code is generated by Data Source Configuration Wizard
            // Fill a SqlDataSource
            sqlDataSource1.Fill();
        }

        private void type_check_CheckedChanged(object sender, EventArgs e)
        {
            
        }

        private void create_new_btn_Click(object sender, EventArgs e)
        {
            New_Employee form = new New_Employee();
            form.Show(this);
        }

        private void refresh_btn_Click(object sender, EventArgs e)
        {
            search_inp.Text = "";
            sqlDataSource1.RebuildResultSchema();
            sqlDataSource1.Fill();
            list.Update();
        }



        private void gridView1_DoubleClick(object sender, EventArgs e)
        {
            if (gridView1.DataRowCount > 0)
            {
                Edit_Employee edit_employee = new Edit_Employee(Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns["Code"])));
                edit_employee.Show();
            }
        }

        private void search_inp_EditValueChanged(object sender, EventArgs e)
        {
            if (search_inp.ContainsFocus == true)
            {
                gridView1.ApplyFindFilter(search_inp.Text);
            }
        }
    }
}
